import { test, expect } from '@playwright/test';

test.describe('Active Sessions Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should display all active sessions and allow logout of specific sessions', async ({ page }) => {
    // Verify profile page loads
    const profileHeader = page.getByRole('heading', { name: /profile/i });
    await expect(profileHeader).toBeVisible();

    // Verify active sessions section is visible
    const sessionsSection = page.getByRole('region', { name: /active sessions/i });
    await expect(sessionsSection).toBeVisible();

    // Verify session list is displayed
    const sessionList = page.getByRole('list');
    await expect(sessionList).toBeVisible();

    // Verify session items are present
    const sessionItems = page.getByRole('listitem');
    await expect(sessionItems).toHaveCount(3);

    // Verify session details are visible
    const sessionDetails = page.getByText(/Chrome/i);
    await expect(sessionDetails).toBeVisible();

    const sessionLocation = page.getByText(/New York/i);
    await expect(sessionLocation).toBeVisible();

    // Verify logout button is visible for each session
    const logoutButtons = page.getByRole('button', { name: /logout/i });
    await expect(logoutButtons).toHaveCount(3);

    // Logout of the first session
    const firstLogoutButton = logoutButtons.first();
    await firstLogoutButton.click();

    // Verify logout confirmation modal appears
    const logoutModal = page.getByRole('dialog', { name: /confirm logout/i });
    await expect(logoutModal).toBeVisible();

    // Confirm logout
    const confirmLogoutButton = page.getByRole('button', { name: /confirm/i });
    await confirmLogoutButton.click();

    // Verify session is removed from list
    await expect(sessionItems).toHaveCount(2);

    // Verify success message appears
    const successMessage = page.getByText(/session logged out successfully/i);
    await expect(successMessage).toBeVisible();
  });

  test('should handle edge case of no active sessions', async ({ page }) => {
    // Navigate to profile page
    await page.goto('/profile');

    // Intercept API call to clear sessions
    await page.route('**/api/sessions', route => {
      route.abort();
    });

    // Click button to clear all sessions
    const clearSessionsButton = page.getByRole('button', { name: /clear all sessions/i });
    await clearSessionsButton.click();

    // Verify empty state message is displayed
    const emptyStateMessage = page.getByText(/no active sessions found/i);
    await expect(emptyStateMessage).toBeVisible();

    // Verify session list is empty
    const sessionList = page.getByRole('list');
    await expect(sessionList).toHaveCount(0);

    // Verify logout button is not visible
    const logoutButtons = page.getByRole('button', { name: /logout/i });
    await expect(logoutButtons).not.toBeVisible();

    // Verify user can still access profile settings
    const settingsLink = page.getByRole('link', { name: /settings/i });
    await expect(settingsLink).toBeVisible();
  });
});
